insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Language Techniques and Terminology'), 'Word classes', 'L1.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Language Techniques and Terminology'), 'Figurative language', 'L1.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Language Techniques and Terminology'), 'Sound and rhetorical devices', 'L1.3', 3);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Language Techniques and Terminology'), 'Tone, register and connotation', 'L1.4', 4);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'c9bc9009-7cb9-44b2-b893-15655325f079'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Word classes', 'In “The ancient door creaked slowly open”, which word is an adverb?', 'door', 'slowly', 'ancient', 'creaked', 'B', '“Slowly” describes how the door creaked. “Ancient” is an adjective and “creaked” is the verb.', 'foundation', 'applied', 'AO2'),
  (2, 'Word classes', 'In “She whispered nervously into the darkness”, which word is the verb?', 'into', 'nervously', 'whispered', 'darkness', 'C', '“Whispered” is the action. “Nervously” is an adverb and “darkness” is a noun.', 'foundation', 'applied', 'AO2'),
  (3, 'Word classes', 'What is an abstract noun?', 'A noun for an object, like “a table”', 'A noun for a group, like “a flock”', 'A noun for an idea or feeling, like “hope”', 'A noun for a named place, like “London”', 'C', 'Abstract nouns name things you cannot touch: hope, fear, freedom.', 'foundation', 'recall', 'AO1'),
  (4, 'Word classes', 'Which sentence uses a modal verb?', 'You are leaving before it gets dark.', 'You must leave before it gets dark.', 'You left before it got dark.', 'You have left before it got dark.', 'B', 'Modal verbs (must, could, should, might, will) show certainty, possibility or obligation.', 'foundation', 'applied', 'AO2'),
  (5, 'Word classes', 'In “They watched the storm from the window”, which word is a pronoun?', 'window', 'They', 'storm', 'watched', 'B', '“They” stands in place of a noun.', 'foundation', 'applied', 'AO2'),
  (6, 'Figurative language', '“The angry sea threw itself at the rocks” mainly uses…', 'personification', 'alliteration', 'hyperbole', 'a simile', 'A', 'The sea is given human feelings and actions (“angry”, “threw itself”).', 'foundation', 'applied', 'AO2'),
  (7, 'Figurative language', 'Which of these is a simile?', 'Her eyes were chips of ice.', 'Her icy eyes stared coldly.', 'Her eyes were as cold as ice.', 'Her eyes: cold, icy, unblinking.', 'C', 'A simile compares using “like” or “as”. “Chips of ice” is a metaphor.', 'foundation', 'applied', 'AO2'),
  (8, 'Figurative language', 'What is pathetic fallacy?', 'An exaggerated emotional claim', 'Giving an object a human name', 'Weather or setting that reflects a mood', 'A character feeling sorry for themselves', 'C', 'For example, a storm breaking as a character becomes furious.', 'foundation', 'recall', 'AO1'),
  (9, 'Figurative language', '“I’ve told you a million times” is an example of…', 'hyperbole', 'metaphor', 'juxtaposition', 'oxymoron', 'A', 'Deliberate exaggeration for effect.', 'foundation', 'applied', 'AO2'),
  (10, 'Figurative language', 'Which phrase is an oxymoron?', 'rolling thunder', 'silent night', 'deafening silence', 'quiet whisper', 'C', 'An oxymoron puts two contradictory words together. A “quiet whisper” is not a contradiction.', 'foundation', 'applied', 'AO2'),
  (11, 'Sound and rhetorical devices', '“Silent, slow, the snake slid across the sand” mainly uses…', 'plosive sounds', 'onomatopoeia', 'sibilance', 'assonance', 'C', 'Repeated “s” sounds create a hissing, sinister effect.', 'foundation', 'applied', 'AO2'),
  (12, 'Sound and rhetorical devices', 'What is a rhetorical question?', 'A question asked by a character in speech', 'A question repeated to add emphasis', 'A question asked for effect, not for an answer', 'A question the writer answers straight away', 'C', 'It makes the reader think, e.g. “How can we let this happen?”', 'foundation', 'recall', 'AO1'),
  (13, 'Sound and rhetorical devices', '“Education, education, education” mainly uses…', 'repetition', 'alliteration', 'antithesis', 'sibilance', 'A', 'The same word is repeated to stress its importance.', 'foundation', 'applied', 'AO2'),
  (14, 'Sound and rhetorical devices', 'What is the “rule of three” (tricolon)?', 'Using three adjectives before a noun', 'Asking three questions in the opening', 'Grouping three ideas together for impact', 'Splitting an argument into three paragraphs', 'C', 'E.g. “cheap, fast and reliable”. Three items feel complete and memorable.', 'foundation', 'recall', 'AO1'),
  (15, 'Sound and rhetorical devices', 'Which phrase uses harsh plosive sounds?', 'murmuring, mellow, mild', 'soft, silken, smooth', 'bitter, broken, battered', 'lulling, lilting, low', 'C', 'Plosives are “b”, “p”, “t”, “d”, “k” and “g”: sounds that burst out.', 'foundation', 'applied', 'AO2'),
  (16, 'Tone, register and connotation', 'A writer calls a house a “lair” instead of a “home”. What does this suggest?', 'Neglect and a sense of poverty', 'Danger and something predatory', 'Comfort and family warmth', 'Wealth and a sense of luxury', 'B', 'A lair is where a wild animal hides, so it connotes threat.', 'foundation', 'applied', 'AO2'),
  (17, 'Tone, register and connotation', 'Which sentence has the most formal register?', 'Just so you know, we’ve called it off.', 'Bad news, everyone: the event isn’t happening now.', 'Sorry, but the event is off now, mate.', 'We regret to inform you the event is cancelled.', 'D', 'Formal register uses impersonal, standard phrasing with no slang or contractions.', 'foundation', 'applied', 'AO2'),
  (18, 'Tone, register and connotation', 'A town is described as “grey, tired and forgotten”. The tone is best described as…', 'comic and light', 'bleak and melancholy', 'warm and nostalgic', 'furious and accusing', 'B', 'The adjectives suggest sadness and decline rather than anger or affection.', 'foundation', 'applied', 'AO2'),
  (19, 'Tone, register and connotation', 'What is the difference between denotation and connotation?', 'Denotation is a word’s sound; connotation its spelling', 'Denotation is literal; connotation is what a word suggests', 'Denotation is formal language; connotation is slang', 'Connotation is literal; denotation is what a word suggests', 'B', '“Red” denotes a colour but can connote danger, anger or passion.', 'higher', 'recall', 'AO1'),
  (20, 'Tone, register and connotation', 'Which describes a sardonic tone?', 'Formal, neutral and purely factual', 'Mocking and scornful, with dry humour', 'Anxious, hesitant and uncertain', 'Gentle, warm and affectionate throughout', 'B', 'Sardonic means grimly mocking.', 'higher', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Language Techniques and Terminology') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

