insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Structure and Sentence Forms'), 'Whole-text structure', 'L2.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Structure and Sentence Forms'), 'Sentence forms and punctuation for effect', 'L2.2', 2);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'c9bc9009-7cb9-44b2-b893-15655325f079'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Whole-text structure', 'Which is a structural feature rather than a language feature?', 'A shift in focus from setting to a character', 'Alliteration in the opening line', 'A verb with violent, threatening connotations', 'A simile describing the stormy sky', 'A', 'Structure is about how the text is organised and where the focus moves, not individual word choices.', 'foundation', 'recall', 'AO1'),
  (2, 'Whole-text structure', 'What is a cyclical structure?', 'The same sentence is repeated throughout', 'The text keeps alternating between two narrators', 'The text is told in reverse time order', 'The ending returns to the opening idea or setting', 'D', 'Returning to the start can suggest nothing has changed, or highlight how much has.', 'foundation', 'recall', 'AO1'),
  (3, 'Whole-text structure', 'Why might a writer open with a one-line paragraph?', 'To grab attention and create intrigue', 'To introduce the main characters at once', 'To give a full summary of the plot', 'To slow the pace with long description', 'A', 'A short, isolated line stands out and raises questions.', 'foundation', 'recall', 'AO1'),
  (4, 'Whole-text structure', 'A narrative suddenly jumps back to a character’s childhood. This is…', 'a cyclical ending', 'a flashback', 'a cliffhanger', 'foreshadowing', 'B', 'A flashback moves the narrative back in time.', 'foundation', 'recall', 'AO1'),
  (5, 'Whole-text structure', 'What is foreshadowing?', 'Placing two contrasting settings together', 'Ending on an unresolved moment', 'Describing events from the distant past', 'Hinting at events that will happen later', 'D', 'E.g. dark clouds gathering before a tragedy.', 'foundation', 'recall', 'AO1'),
  (6, 'Whole-text structure', 'Zooming in from a wide view of a city to a single window is an example of…', 'narrowing the focus', 'a flashback', 'a cyclical structure', 'a change of narrator', 'A', 'The “camera” moves from the general to the specific, drawing the reader in.', 'foundation', 'applied', 'AO2'),
  (7, 'Whole-text structure', 'What effect does holding back key information usually create?', 'Suspense and curiosity', 'Humour and light relief', 'Calm and reassurance', 'Closure and resolution', 'A', 'The reader wants to find out what is being withheld.', 'foundation', 'applied', 'AO2'),
  (8, 'Whole-text structure', 'What is a cliffhanger?', 'Returning to the opening at the end', 'Opening with a description of the weather', 'Ending a section at a moment of tension', 'A sudden change of narrative voice', 'C', 'It leaves the outcome unresolved to keep the reader hooked.', 'foundation', 'recall', 'AO1'),
  (9, 'Whole-text structure', 'In a structure answer, a “shift” means…', 'a change in the font or layout', 'any use of figurative language', 'the writer’s choice of a single word', 'a change in focus, time, place or mood', 'D', 'Tracking shifts is the core of a structure answer.', 'foundation', 'recall', 'AO1'),
  (10, 'Whole-text structure', 'A text moves from calm description to a sudden violent event. This creates…', 'a repeat of the opening', 'a contrast in mood', 'a flashback to the past', 'a cyclical structure', 'B', 'The shift from calm to violence makes the event more shocking.', 'foundation', 'applied', 'AO2'),
  (11, 'Sentence forms and punctuation for effect', 'What is the main effect of a short simple sentence after several long ones?', 'It shows the narrator is confused', 'It creates impact or a sudden pause', 'It makes the writing sound more formal', 'It slows the pace and adds more detail', 'B', 'The contrast in length makes the short sentence stand out.', 'foundation', 'applied', 'AO2'),
  (12, 'Sentence forms and punctuation for effect', 'Which is a complex sentence?', 'Raining, cold, grey: a walk anyway.', 'It was raining and we went for a walk.', 'Although it was raining, we went for a walk.', 'It was raining. We went out for a walk.', 'C', 'A complex sentence has a main clause and a subordinate clause (“Although it was raining”). “And” makes a compound sentence.', 'foundation', 'applied', 'AO2'),
  (13, 'Sentence forms and punctuation for effect', 'What is a minor sentence?', 'Two main clauses joined by “and”', 'A sentence with no main verb, e.g. “Silence.”', 'A sentence with one clause, e.g. “He ran.”', 'Any sentence under five words long', 'B', '“He ran.” is a simple sentence: it has a verb.', 'higher', 'recall', 'AO1'),
  (14, 'Sentence forms and punctuation for effect', 'Why might a writer use an ellipsis (…)?', 'To link two closely related main clauses', 'To introduce a list or an explanation', 'To show a pause, trailing off or something unsaid', 'To add extra information that is not essential', 'C', 'The other options describe a colon, a semicolon and brackets.', 'foundation', 'recall', 'AO1'),
  (15, 'Sentence forms and punctuation for effect', 'What does a colon most often do?', 'Marks a pause in the middle of speech', 'Shows the end of a direct question', 'Shows that a letter has been missed out', 'Introduces an explanation, list or example', 'D', 'E.g. “She had one aim: to win.”', 'foundation', 'recall', 'AO1'),
  (16, 'Sentence forms and punctuation for effect', '“He ran, stumbled, fell, rose” is an example of…', 'asyndetic listing', 'a minor sentence', 'syndetic listing', 'a rhetorical question', 'A', 'Asyndeton leaves out “and”, speeding the pace. Syndetic lists use conjunctions.', 'higher', 'applied', 'AO2'),
  (17, 'Sentence forms and punctuation for effect', '“He ran and ran and ran” uses…', 'asyndeton', 'ellipsis', 'a minor sentence', 'polysyndeton', 'D', 'Repeating “and” makes the action feel endless or exhausting.', 'higher', 'applied', 'AO2'),
  (18, 'Sentence forms and punctuation for effect', 'Which sentence begins with a fronted adverbial?', 'Without a sound, the cat crept away.', 'The silent cat crept slowly away.', 'The cat, silent, crept slowly away.', 'The cat crept away without a sound.', 'A', 'The adverbial phrase (“Without a sound”) is moved to the front for emphasis.', 'foundation', 'applied', 'AO2'),
  (19, 'Sentence forms and punctuation for effect', 'What is the effect of opening with “Run!”?', 'A minor sentence slowing the pace', 'An imperative creating urgency', 'A question inviting the reader in', 'A statement giving background', 'B', 'An imperative is a command; on its own it feels urgent.', 'foundation', 'applied', 'AO2'),
  (20, 'Sentence forms and punctuation for effect', 'Which use of a semicolon is correct?', 'It was late; and the streets were empty.', 'It was late; because the streets were empty.', 'It was late; the streets were empty.', 'The streets; were empty and it was late.', 'C', 'A semicolon joins two complete, related main clauses without a conjunction.', 'foundation', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Structure and Sentence Forms') and s.name = v.sub
