insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'c9bc9009-7cb9-44b2-b893-15655325f079'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Questions 1 and 2: retrieval and language', 'In AQA Paper 1, how many marks is Question 1 worth?', '2 marks', '8 marks', '4 marks', '12 marks', 'C', 'Q1 asks for four things from a given section, one mark each.', 'foundation', 'recall', 'AO1'),
  (2, 'Questions 1 and 2: retrieval and language', 'What does Paper 1 Question 1 ask you to do?', 'Evaluate a statement about the source', 'List four things from a set part of the source', 'Comment on how the whole source is structured', 'Analyse how the writer uses language', 'B', 'It is a short retrieval question from specified lines.', 'foundation', 'recall', 'AO1'),
  (3, 'Questions 1 and 2: retrieval and language', 'Paper 1 Question 2 (8 marks) asks you to analyse…', 'four true statements from the source', 'how language is used in a short extract', 'how the whole source has been structured', 'the viewpoint compared with another text', 'B', 'Q2 is language analysis on a section; Q3 is structure across the whole source.', 'foundation', 'recall', 'AO1'),
  (4, 'Questions 1 and 2: retrieval and language', 'Which is the strongest start to a Paper 1 Question 2 paragraph?', 'I think this extract is well written', 'The writer uses lots of techniques here', 'There are many interesting words here', 'The verb “clawed” suggests desperation', 'D', 'Start with a precise reference and what it suggests, not a general comment.', 'foundation', 'applied', 'AO2'),
  (5, 'Questions 1 and 2: retrieval and language', 'Which comment best explains effect in Question 2?', '“Shattered” suggests the silence breaks suddenly and violently', '“Shattered” describes what happens to the silence in the scene', '“Shattered” is a good word that makes the reader want to read on', '“Shattered” is a seven-letter verb written in the past tense', 'A', 'It explores what the word suggests. The others are vague, feature-spotting or retelling.', 'foundation', 'applied', 'AO2'),
  (6, 'Questions 1 and 2: retrieval and language', 'What type of text is the Paper 1 source?', 'A modern newspaper article or speech', 'A 20th or 21st-century fiction extract', 'A 19th-century non-fiction text', 'Two non-fiction texts from two centuries', 'B', 'Paper 1 uses one literature fiction extract; Paper 2 uses two non-fiction sources.', 'foundation', 'recall', 'AO1'),
  (7, 'Questions 1 and 2: retrieval and language', 'Roughly how long should you spend on Paper 1 Question 1?', 'About 15 minutes', 'About 5 minutes', 'About 25 minutes', 'About 45 minutes', 'B', 'It is only 4 marks, so keep it brief and save time for Q4 and Q5.', 'foundation', 'recall', 'AO1'),
  (8, 'Question 3: structure', 'Paper 1 Question 3 asks you to analyse…', 'how far you agree with a given statement', 'how the writer has structured the whole text', 'the language used in a short section', 'how the writer presents their viewpoint', 'B', 'Q3 is about structure across the whole source.', 'foundation', 'recall', 'AO1'),
  (9, 'Question 3: structure', 'Which point is most relevant to Paper 1 Question 3?', 'The writer uses alliteration in line 3', 'The focus shifts from the storm to the boy inside', 'A metaphor describes the storm in the fourth line', 'The adjective “raging” suggests danger', 'B', 'Only the first is about structure; the others are language points.', 'foundation', 'applied', 'AO2'),
  (10, 'Question 3: structure', 'How many marks is Paper 1 Question 3 worth?', '8 marks', '4 marks', '12 marks', '20 marks', 'A', 'Q2 and Q3 are both 8 marks.', 'foundation', 'recall', 'AO1'),
  (11, 'Question 3: structure', 'What is a good way to organise a Question 3 answer?', 'Pick the three best quotes for language', 'Focus on the characters’ feelings', 'Start with your opinion of the story', 'Follow the text from beginning to end', 'D', 'Working through the opening, middle and end helps you track shifts in focus.', 'foundation', 'recall', 'AO1'),
  (12, 'Question 3: structure', 'Why might a writer end an extract with an unanswered question?', 'To return to the setting from the opening', 'To summarise everything that has happened', 'To slow the pace with extra description', 'To create mystery and make the reader want more', 'D', 'Leaving things unresolved keeps the reader engaged.', 'foundation', 'applied', 'AO2'),
  (13, 'Question 3: structure', 'Which is NOT usually part of a structure answer?', 'Where the writer shifts the focus', 'How the ending links to the start', 'The connotations of a single adjective', 'How the opening sets the scene', 'C', 'Connotations of individual words are a language point (Q2).', 'higher', 'applied', 'AO2'),
  (14, 'Question 3: structure', 'Paper 1 Question 3 is assessed against which objective?', 'AO2 (language and structure)', 'AO4 (evaluating texts)', 'AO1 (retrieval and summary)', 'AO3 (comparing viewpoints)', 'A', 'AO2 covers how writers use language and structure.', 'higher', 'recall', 'AO1'),
  (15, 'Question 4: evaluation', 'How many marks is Paper 1 Question 4 worth?', '20 marks', '16 marks', '40 marks', '12 marks', 'A', 'Q4 is the biggest reading question on Paper 1.', 'foundation', 'recall', 'AO1'),
  (16, 'Question 4: evaluation', 'What does Paper 1 Question 4 ask you to do?', 'Write a description from a picture', 'Evaluate a statement about part of the source', 'Summarise the differences between sources', 'Compare two writers’ perspectives', 'B', 'It gives a statement from a “student” and asks how far you agree.', 'foundation', 'recall', 'AO1'),
  (17, 'Question 4: evaluation', 'Which sentence shows evaluation in Question 4?', 'The writer succeeds in making the scene threatening because…', 'The writer uses a lot of interesting language in this part', 'The writer begins the paragraph with a simile about it', 'In this part of the text there is a description of a house', 'A', 'Evaluation judges how well the writer achieves an effect, then explains why.', 'foundation', 'applied', 'AO2'),
  (18, 'Question 4: evaluation', 'Roughly how long should you spend on Paper 1 Question 4?', 'About 5 minutes', 'About 45 minutes', 'About 10 minutes', 'About 20 minutes', 'D', 'AQA suggests about 20 minutes for 20 marks.', 'foundation', 'recall', 'AO1'),
  (19, 'Question 4: evaluation', 'Paper 1 Question 4 is marked against which objective?', 'AO2 (language and structure)', 'AO5 (content and organisation)', 'AO3 (compare viewpoints)', 'AO4 (critically evaluate texts)', 'D', 'AO4 is evaluation, supported by textual references.', 'higher', 'recall', 'AO1'),
  (20, 'Question 4: evaluation', 'In Question 4, do you have to agree with the statement?', 'Yes, but you should avoid giving an opinion', 'No, you must disagree to show critical skill', 'Yes, since the examiner wrote the statement', 'No: agree, disagree or partly, with reasons', 'D', 'Any view is fine if you justify it with evidence from the text.', 'foundation', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Paper 1 Reading: Creative Reading') and s.name = v.sub
