insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Paper 2 Reading: Viewpoints and Perspectives'), 'Question 3: language', 'L4.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Paper 2 Reading: Viewpoints and Perspectives'), 'Question 4: comparing perspectives', 'L4.3', 3);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'c9bc9009-7cb9-44b2-b893-15655325f079'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Questions 1 and 2: true statements and summary', 'What does Paper 2 Question 1 ask you to do?', 'Summarise the differences between sources', 'Analyse how the writer uses language', 'List four things from a set part of the source', 'Choose four true statements from eight', 'D', 'You shade four boxes. Listing four things is Paper 1 Q1.', 'foundation', 'recall', 'AO1'),
  (2, 'Questions 1 and 2: true statements and summary', 'What does Paper 2 Question 2 ask for?', 'A summary of differences or similarities in both sources', 'An analysis of the language used in one of the sources', 'A comparison of the writers’ methods and perspectives', 'An evaluation of how successful one source is overall', 'A', 'Q2 is about content (what is different), not methods. Methods and perspectives are Q4.', 'foundation', 'recall', 'AO1'),
  (3, 'Questions 1 and 2: true statements and summary', 'How many marks is Paper 2 Question 2 worth?', '4 marks', '16 marks', '12 marks', '8 marks', 'D', 'Q1 is 4, Q2 is 8, Q3 is 12 and Q4 is 16.', 'foundation', 'recall', 'AO1'),
  (4, 'Questions 1 and 2: true statements and summary', 'What sources are used in Paper 2?', 'One literary fiction extract from the 20th or 21st century', 'Two modern newspaper articles on the same topic', 'Two poems from different time periods on one theme', 'Two non-fiction texts: one 19th-century, one 20th/21st', 'D', 'Paper 2 always pairs a 19th-century and a modern non-fiction source.', 'foundation', 'recall', 'AO1'),
  (5, 'Questions 1 and 2: true statements and summary', 'Paper 2 Question 2 mainly tests…', 'inference and synthesis across both sources', 'evaluation of the writers’ overall success', 'technical accuracy in your own writing', 'analysis of the writers’ language choices', 'A', 'AO1: identify and interpret ideas, and synthesise evidence from different texts.', 'foundation', 'recall', 'AO1'),
  (6, 'Questions 1 and 2: true statements and summary', 'Which is the best sentence for Paper 2 Question 2?', 'Source A is better written than Source B is overall', 'Both sources are about children and both are interesting', 'Source A uses lots of adjectives, whereas Source B uses verbs', 'Source A’s children seem carefree, whereas Source B’s seem exhausted', 'D', 'It infers a clear difference in content. The second is about methods (Q4) and the third is evaluation.', 'higher', 'applied', 'AO2'),
  (7, 'Questions 1 and 2: true statements and summary', 'What does “synthesise” mean in Paper 2 Question 2?', 'Copy quotations from each source in turn', 'Analyse the methods each writer uses in turn', 'Evaluate which source is more effective overall', 'Combine information from both sources into one point', 'D', 'You draw ideas together from both texts.', 'foundation', 'recall', 'AO1'),
  (8, 'Question 3: language', 'How many marks is Paper 2 Question 3 worth?', '12 marks', '4 marks', '8 marks', '16 marks', 'A', 'It is the language question on Paper 2.', 'foundation', 'recall', 'AO1'),
  (9, 'Question 3: language', 'Paper 2 Question 3 asks you to analyse…', 'how the writer structures the whole source', 'how one writer uses language to create effects', 'the differences between the two sources', 'how both writers present their perspectives', 'B', 'Q3 focuses on language in one source; Q4 compares both.', 'foundation', 'recall', 'AO1'),
  (10, 'Question 3: language', 'Which source is Paper 2 Question 3 usually about?', 'Usually Source A, the modern text', 'Usually Source B, as the question says', 'Usually Source A, then both together', 'Both sources, compared together', 'B', 'The question tells you which source to use, normally Source B.', 'foundation', 'recall', 'AO1'),
  (11, 'Question 3: language', 'In a 19th-century text, “a most wretched and pitiable sight” shows…', 'a neutral, factual tone with no bias or emotion', 'a casual, chatty tone meant to entertain', 'an emotive, formal style that builds sympathy', 'sarcasm used to mock the subject', 'C', 'The heightened, formal vocabulary is designed to make readers pity the subject.', 'foundation', 'applied', 'AO2'),
  (12, 'Question 3: language', 'Which comment is most analytical about language in Question 3?', 'The writer uses a superlative here, which is a type of adjective you can identify', 'The writer uses the phrase “most wretched” in the second paragraph of the source', 'The superlative “most wretched” intensifies the misery, making readers pity the boys', 'This makes the reader want to read on and find out more about the boys’ situation', 'C', 'It names the method, explores its effect and links it to the reader.', 'higher', 'applied', 'AO2'),
  (13, 'Question 3: language', 'What is the effect of direct address (“you”) in a speech?', 'It makes the speech seem fictional rather than real', 'It involves the audience and makes the issue personal', 'It shows the speaker is unsure of their argument', 'It makes the speech sound more formal and distant', 'B', 'Speaking directly to the reader or listener draws them in.', 'foundation', 'applied', 'AO2'),
  (14, 'Question 3: language', 'Which is usually true of 19th-century sources?', 'They use longer sentences and formal vocabulary', 'They are mostly written as poems or song lyrics', 'They are written in modern slang and text-speak', 'They avoid opinion and are purely factual', 'A', 'Expect long, complex sentences and vocabulary that can feel old-fashioned.', 'foundation', 'recall', 'AO1'),
  (15, 'Question 4: comparing perspectives', 'How many marks is Paper 2 Question 4 worth?', '20 marks', '16 marks', '12 marks', '8 marks', 'B', 'Q4 is the comparison question.', 'foundation', 'recall', 'AO1'),
  (16, 'Question 4: comparing perspectives', 'Paper 2 Question 4 asks you to compare…', 'the writers’ perspectives and the methods they use', 'the differences in what happens in each source', 'the facts in each source and which is more accurate', 'the length and layout of each source on the page', 'A', 'You compare attitudes and how they are conveyed. Content differences are Q2.', 'foundation', 'recall', 'AO1'),
  (17, 'Question 4: comparing perspectives', 'Which assessment objective does Paper 2 Question 4 test?', 'AO3 (compare ideas and perspectives)', 'AO1 (identify and interpret ideas)', 'AO4 (evaluate texts critically)', 'AO6 (technical accuracy in writing)', 'A', 'AO3 is comparison across texts.', 'higher', 'recall', 'AO1'),
  (18, 'Question 4: comparing perspectives', 'Which connective best signals a contrast?', 'likewise', 'furthermore', 'whereas', 'similarly', 'C', '“Whereas” contrasts; the others add or show similarity.', 'foundation', 'applied', 'AO2'),
  (19, 'Question 4: comparing perspectives', 'Which sentence best compares perspectives?', 'Writer A’s text is longer than Writer B’s and has more paragraphs', 'Writer A uses a metaphor and Writer B uses a simile in their text', 'While Writer A finds the city thrilling, Writer B sees it as cruel', 'Writer A writes about the city and so does Writer B in their text', 'C', 'It compares attitudes. The others compare topic, features or length.', 'foundation', 'applied', 'AO2'),
  (20, 'Question 4: comparing perspectives', 'In Paper 2 Question 4, what does “methods” refer to?', 'The language and structure choices writers make', 'The research the writers did before writing', 'The way you plan your answer in the exam', 'The way the sources are printed on the page', 'A', 'Methods are how writers convey their perspectives.', 'foundation', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Paper 2 Reading: Viewpoints and Perspectives') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

