insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'English Language'), 'Writing', 'L5', 'Papers 1 and 2', 5);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Writing'), 'Paper 1 Question 5: descriptive and narrative writing', 'L5.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Writing'), 'Paper 2 Question 5: writing to present a viewpoint', 'L5.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Writing'), 'Form, audience and purpose', 'L5.3', 3);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'c9bc9009-7cb9-44b2-b893-15655325f079'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Paper 1 Question 5: descriptive and narrative writing', 'How many marks is Question 5 on each paper worth?', '20 marks', '24 marks', '40 marks', '16 marks', 'C', 'The writing question is half of each paper’s 80 marks.', 'foundation', 'recall', 'AO1'),
  (2, 'Paper 1 Question 5: descriptive and narrative writing', 'How are the 40 marks for Question 5 split?', '24 content and organisation, 16 technical accuracy', '20 content and organisation, 20 technical accuracy', '16 content and organisation, 24 technical accuracy', '30 content and organisation, 10 technical accuracy', 'A', 'AO5 (content and organisation) is 24 marks; AO6 (technical accuracy) is 16.', 'higher', 'recall', 'AO1'),
  (3, 'Paper 1 Question 5: descriptive and narrative writing', 'Paper 1 Question 5 asks you to write…', 'an article, letter or speech with a viewpoint', 'a review of the source extract you read', 'a summary of the source text in your words', 'a description or a story, from a choice of tasks', 'D', 'Paper 1 is creative writing; Paper 2 Q5 is viewpoint writing.', 'foundation', 'recall', 'AO1'),
  (4, 'Paper 1 Question 5: descriptive and narrative writing', 'Roughly how long should you spend on Question 5?', 'About 20 minutes', 'About 1 hour 15 minutes', 'About 10 minutes', 'About 45 minutes', 'D', 'Including around 5 minutes to plan and 5 to check.', 'foundation', 'recall', 'AO1'),
  (5, 'Paper 1 Question 5: descriptive and narrative writing', 'Which opening is most likely to engage the reader of a description?', 'Once upon a time there was a very cold winter morning.', 'In this piece I am going to describe a winter morning.', 'Frost clung to the windows like lace, and nothing moved.', 'It was a cold day and it was winter and it was cold.', 'C', 'It drops the reader straight into a precise, sensory image.', 'foundation', 'applied', 'AO2'),
  (6, 'Paper 1 Question 5: descriptive and narrative writing', 'In a narrative, why is it often better to cover a short time span?', 'It is a rule in the mark scheme for the stories you write', 'It means you can include many more characters and events', 'It allows detailed, controlled writing rather than a rushed plot', 'It means the story can leave out a proper ending to save time', 'C', 'In 45 minutes, a single moment written well beats a whole life summarised.', 'higher', 'recall', 'AO1'),
  (7, 'Paper 1 Question 5: descriptive and narrative writing', 'Which sentence shows rather than tells?', 'She was nervous. She was really very nervous.', 'Her hands shook as she fumbled with the key.', 'She felt scared, so she was nervous and afraid.', 'She was very nervous about opening the door.', 'B', 'The reader infers nerves from her actions instead of being told.', 'foundation', 'applied', 'AO2'),
  (8, 'Paper 2 Question 5: writing to present a viewpoint', 'Paper 2 Question 5 asks you to…', 'write a short story with a twist at the very end', 'summarise both sources in your own words and style', 'write a description based on a picture you are given in the exam', 'write to present a viewpoint, e.g. a letter, article or speech', 'D', 'You are given a statement and asked to argue or persuade in a set form.', 'foundation', 'recall', 'AO1'),
  (9, 'Paper 2 Question 5: writing to present a viewpoint', 'What is the most effective way to handle a counter-argument?', 'Acknowledge the other view, then rebut it with evidence', 'Agree with both sides equally in each paragraph', 'Ignore the other view so your argument looks stronger', 'End with the other view so it is fresh in the mind', 'A', 'Dealing with the opposing view and dismissing it makes your argument more convincing.', 'foundation', 'applied', 'AO2'),
  (10, 'Paper 2 Question 5: writing to present a viewpoint', 'In a persuasive article, statistics are mainly used to…', 'give the writer’s personal anecdotes', 'make the argument seem factual and credible', 'make the writing sound more emotional', 'make the article longer and more detailed', 'B', 'Numbers suggest evidence and authority.', 'foundation', 'applied', 'AO2'),
  (11, 'Paper 2 Question 5: writing to present a viewpoint', 'Which sentence uses emotive language?', 'Around 20% of homes in the area lack proper heating systems.', 'Innocent children are left to shiver in freezing, filthy homes.', 'The council will discuss local housing at Monday’s meeting.', 'Housing is one of a number of issues in the local area.', 'B', 'Words like “innocent”, “shiver” and “filthy” are chosen to provoke feeling.', 'foundation', 'applied', 'AO2'),
  (12, 'Paper 2 Question 5: writing to present a viewpoint', 'Which is the most effective ending for a speech?', 'Anyway, those are just a few things I wanted to say.', 'That is the end of my speech, thank you for listening.', 'In conclusion, there are many sides to this issue.', 'So I ask you: will you act now, before it is too late?', 'D', 'It ends on a direct, urgent call to action.', 'foundation', 'applied', 'AO2'),
  (13, 'Paper 2 Question 5: writing to present a viewpoint', 'What is an anecdote, and why use one in an argument?', 'A statistic that proves the point is true and reliable', 'An expert quotation that adds authority', 'A joke that lightens the end of the argument', 'A short personal story that makes the point relatable', 'D', 'Anecdotes make abstract issues feel real and human.', 'foundation', 'recall', 'AO1'),
  (14, 'Paper 2 Question 5: writing to present a viewpoint', 'Which feature belongs in a formal letter?', 'A title and a cast list of the characters', 'A chatty opening such as “Hi guys, how are you doing?”', 'A headline with bold subheadings throughout', 'A formal greeting and sign-off, e.g. “Yours faithfully”', 'D', 'Headlines and subheadings belong in articles or leaflets.', 'foundation', 'recall', 'AO1'),
  (15, 'Form, audience and purpose', 'In a writing task, “audience” means…', 'the time period the text is set in', 'the reason for writing, e.g. to persuade', 'who the text is written for, e.g. parents', 'the type of text, e.g. a letter', 'C', 'Form is the type of text; purpose is why you are writing.', 'foundation', 'recall', 'AO1'),
  (16, 'Form, audience and purpose', 'You are writing an article for a broadsheet newspaper. Which register suits it best?', 'Formal, with sophisticated vocabulary', 'Informal and chatty, with lots of slang', 'Very simple, as if for young children', 'Poetic, with rhyme in each line', 'A', 'Broadsheet readers expect a formal, serious register.', 'foundation', 'applied', 'AO2'),
  (17, 'Form, audience and purpose', 'Which is a feature of a speech?', 'A headline and a byline at the top', 'Paragraphs headed with bold subheadings', 'Direct address and questions to the audience', 'An address and the date in the corner', 'C', 'Speeches speak directly to listeners.', 'foundation', 'recall', 'AO1'),
  (18, 'Form, audience and purpose', 'If the purpose is to argue, what should your writing do?', 'Tell a story with characters and a clear plot', 'Put forward a clear viewpoint supported by reasons', 'Describe a place using the five senses', 'Give step-by-step instructions to the reader', 'B', 'Arguing means taking a position and backing it up.', 'foundation', 'recall', 'AO1'),
  (19, 'Form, audience and purpose', 'Writing for teenagers in a school magazine, which approach fits best?', 'Formal and legal, like a contract', 'Full of text-speak and abbreviations', 'Simple and repetitive, like a picture book', 'Lively and engaging, but in Standard English', 'D', 'Match the audience but keep accuracy, which is what the marks reward.', 'foundation', 'applied', 'AO2'),
  (20, 'Form, audience and purpose', 'What does “form” mean in a writing task?', 'The type of text, e.g. a speech or article', 'The tone and mood of the writing', 'Who the text is written for and the reason why', 'The order of paragraphs in the text', 'A', 'Each form has its own conventions.', 'foundation', 'recall', 'AO1')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Writing') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

