insert into topics (subject_id, name, spec_ref, paper, display_order) values ((select id from subjects where name = 'English Language'), 'Technical Accuracy', 'L6', 'Papers 1 and 2', 6);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy'), 'Punctuation', 'L6.1', 1);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy'), 'Spelling and commonly confused words', 'L6.2', 2);
insert into subtopics (topic_id, name, spec_ref, display_order) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy'), 'Grammar and Standard English', 'L6.3', 3);

insert into questions (topic_id, subtopic_id, question_text, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty, question_type, ao_weighting, generation_batch_id, content_hash, active, created_at)
select s.topic_id, s.id, v.qt, v.a, v.b, v.c, v.d, v.co, v.ex, v.dif, v.qtype, v.ao, 'c9bc9009-7cb9-44b2-b893-15655325f079'::uuid, encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'), true, now() + v.n * interval '1 microsecond'
from (values
  (1, 'Punctuation', 'Which sentence uses an apostrophe correctly?', 'The dog wagged its tail.', 'The dogs’ wagged their tails.', 'The dog wagged it’s tail.', 'The dog wag’s its tail.', 'A', '“Its” (possessive) has no apostrophe; “it’s” means “it is”.', 'foundation', 'applied', 'AO2'),
  (2, 'Punctuation', 'Which sentence contains a comma splice?', 'It was cold; we stayed inside.', 'It was cold, so we stayed inside.', 'It was cold, we stayed inside.', 'Because it was cold, we stayed in.', 'C', 'A comma splice joins two main clauses with only a comma. Use a full stop, semicolon or conjunction.', 'foundation', 'applied', 'AO2'),
  (3, 'Punctuation', 'Which of these needs a question mark at the end?', 'Tell me where you are going', 'I wonder where you are going', 'Where are you going', 'She asked where you were going', 'C', 'Only a direct question takes a question mark. The others are statements or reported (indirect) questions.', 'higher', 'applied', 'AO2'),
  (4, 'Punctuation', 'Which plural possessive is correct?', 'the childrens’ toys', 'the childrens toys', 'the children’s’ toys', 'the children’s toys', 'D', '“Children” is already plural, so add ’s.', 'higher', 'applied', 'AO2'),
  (5, 'Punctuation', 'Which sentence uses a colon correctly?', 'She needed: courage, luck and lots of time.', 'She needed three things, courage: luck and time.', 'She needed three things: courage, luck and time.', 'She: needed courage, luck and lots of time.', 'C', 'A colon follows a complete clause and introduces the list.', 'foundation', 'applied', 'AO2'),
  (6, 'Punctuation', 'Which sentence uses brackets correctly?', 'The castle built (in 1270 still) stands today.', 'The castle (built in 1270) still stands today.', 'The castle (built in 1270 still stands) today.', 'The (castle built) in 1270 still stands today.', 'B', 'Brackets hold extra information; the sentence must still make sense without them.', 'foundation', 'applied', 'AO2'),
  (7, 'Punctuation', 'Where should the comma go in “After the match ended the fans went home”?', 'After “After”', 'After “fans”', 'After “ended”', 'After “match”', 'C', 'The comma separates the opening subordinate clause from the main clause.', 'foundation', 'applied', 'AO2'),
  (8, 'Spelling and commonly confused words', 'Which sentence is correct?', 'They’re going to their house over there.', 'Their going to there house over they’re.', 'They’re going to there house over their.', 'There going to their house over they’re.', 'A', 'They’re = they are; their = belonging to them; there = a place.', 'foundation', 'applied', 'AO2'),
  (9, 'Spelling and commonly confused words', 'Which spelling is correct?', 'definitely', 'definately', 'definitly', 'deffinitely', 'A', 'Remember “finite” inside: de-FINITE-ly.', 'foundation', 'applied', 'AO2'),
  (10, 'Spelling and commonly confused words', 'Which sentence uses “affect” and “effect” correctly?', 'Rain will effect the match; the effect could be huge.', 'Rain will affect the match; the affect could be huge.', 'Rain will effect the match; the affect could be huge.', 'Rain will affect the match; the effect could be huge.', 'D', 'Affect is usually the verb; effect is usually the noun.', 'foundation', 'applied', 'AO2'),
  (11, 'Spelling and commonly confused words', 'Which is correct?', 'I should off known.', 'I should’ve of known.', 'I should of known.', 'I should have known.', 'D', '“Should’ve” sounds like “should of”, but it is short for “should have”.', 'foundation', 'applied', 'AO2'),
  (12, 'Spelling and commonly confused words', 'Which of these is spelled correctly?', 'seperate', 'separate', 'separete', 'sepparate', 'B', 'There is “a rat” in sep-a-rate.', 'foundation', 'applied', 'AO2'),
  (13, 'Spelling and commonly confused words', 'Which sentence uses practise/practice correctly (British English)?', 'I must practise more; practice makes perfect.', 'I must practice more; practise makes perfect.', 'I must practise more; practise makes perfect.', 'I must practice more; practice makes perfect.', 'A', 'In British English, “practise” is the verb and “practice” is the noun.', 'higher', 'applied', 'AO2'),
  (14, 'Spelling and commonly confused words', 'Which word is spelled correctly?', 'necessery', 'neccessary', 'neccesary', 'necessary', 'D', 'One collar (c), two sleeves (ss).', 'foundation', 'applied', 'AO2'),
  (15, 'Grammar and Standard English', 'Which sentence is in Standard English?', 'We was going to the shops.', 'We was gonna go to the shops.', 'Me and him was going shopping.', 'We were going to the shops.', 'D', '“We” takes “were”, not “was”.', 'foundation', 'applied', 'AO2'),
  (16, 'Grammar and Standard English', 'Which sentence uses “I” and “me” correctly?', 'Me and Sam went to the cinema.', 'Sam and me went to the cinema.', 'Sam and I went to the cinema.', 'Myself and Sam went to the cinema.', 'C', 'Take Sam out: “I went”, not “me went”.', 'foundation', 'applied', 'AO2'),
  (17, 'Grammar and Standard English', 'Which sentence keeps the tense consistent?', 'She walks in and sat down quietly.', 'She walked in and sits down quietly.', 'She walked in and sat down quietly.', 'She is walking in and sat down quietly.', 'C', 'Both verbs are in the past tense.', 'foundation', 'applied', 'AO2'),
  (18, 'Grammar and Standard English', 'Which sentence uses “fewer” correctly?', 'There was fewer noise than last year.', 'There was fewer traffic than last year.', 'There was fewer water than last year.', 'There were fewer people than last year.', 'D', '“Fewer” is for things you can count; “less” is for things you cannot.', 'foundation', 'applied', 'AO2'),
  (19, 'Grammar and Standard English', 'Which sentence avoids a double negative?', 'I didn’t do anything wrong.', 'I never did nothing wrong.', 'I didn’t do nothing at all.', 'I didn’t do nothing wrong.', 'A', 'Two negatives (“didn’t” + “nothing”) cancel out in Standard English.', 'foundation', 'applied', 'AO2'),
  (20, 'Grammar and Standard English', 'Which sentence has correct subject–verb agreement?', 'The boxes of chocolates is on the table.', 'The box of chocolates is on the table.', 'The box of chocolates are on the table.', 'The box of chocolates were on the table.', 'B', 'The subject is “box” (singular), so it takes “is”.', 'higher', 'applied', 'AO2')
) as v(n, sub, qt, a, b, c, d, co, ex, dif, qtype, ao)
join subtopics s on s.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy') and s.name = v.sub
where not exists (select 1 from questions q where encode(sha256(convert_to(lower(btrim(regexp_replace(q.question_text, '\s+', ' ', 'g'))), 'UTF8')), 'hex') = encode(sha256(convert_to(lower(btrim(regexp_replace(v.qt, '\s+', ' ', 'g'))), 'UTF8')), 'hex'));

insert into quizzes (topic_id, title, display_order, question_count, cooldown_hours) values ((select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy'), 'Quiz 1', 1, 0, 168);
with ordered as (
  select q.id, row_number() over (order by q.created_at) - 1 as i
  from questions q join subtopics s on s.id = q.subtopic_id
  where q.generation_batch_id = 'c9bc9009-7cb9-44b2-b893-15655325f079'::uuid and q.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy')
)
insert into quiz_questions (quiz_id, question_id, position)
select z.id, o.id, (o.i / 1)::int + 1
from ordered o join quizzes z on z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy') and z.title = 'Quiz ' || ((o.i % 1) + 1);
update quizzes z set question_count = (select count(*) from quiz_questions qq where qq.quiz_id = z.id) where z.topic_id = (select id from topics where subject_id = (select id from subjects where name = 'English Language') and name = 'Technical Accuracy');

